-- ============================================================
-- SEED: Módulo 20 — Academic Connectors (B2)
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'academic-connectors';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo academic-connectors não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 1: Addition Connectors (furthermore, moreover, in addition)
  (cid,1,1,'gap_fill','The study produced reliable results. _____, it was conducted across three different cultural contexts.','Furthermore/Moreover/In addition',NULL,'"Furthermore," "Moreover," and "In addition" add information of equal or greater importance. Any is correct here.','easy'),
  (cid,1,2,'multiple_choice','The new drug reduced inflammation. _____, it had minimal side effects in the trial population.','Moreover','["However","Therefore","Despite","Moreover"]','"Moreover" adds further supporting information. "However" signals contrast; "Therefore" signals result.','easy'),
  (cid,1,3,'gap_fill','The university offers excellent research facilities. _____ (in addition), it provides generous funding for postgraduate students.','In addition',NULL,'"In addition" introduces an additional point. Followed by a comma before the main clause.','easy'),
  (cid,1,4,'multiple_choice','Which connector best completes: "Deforestation destroys biodiversity. _____, it contributes significantly to climate change."','Furthermore','["Although","Consequently","Nevertheless","Furthermore"]','"Furthermore" adds a further, related point to the previous statement about deforestation.','easy'),
  (cid,1,5,'gap_fill','The policy reduced energy consumption. _____, it created thousands of green jobs.','Furthermore/Moreover/In addition',NULL,'Any addition connector works here to introduce an additional positive outcome of the policy.','easy'),
  (cid,1,6,'multiple_choice','Which sentence correctly uses "moreover"?','The proposal was cost-effective; moreover, it was environmentally sustainable.','["The proposal was cost-effective; moreover the it was sustainable.","The proposal was cost-effective; moreover, it was environmentally sustainable.","Moreover the proposal was cost-effective it was sustainable.","The proposal was cost-effective. Moreover it was sustainable."]','"Moreover" follows a semicolon and is followed by a comma. → ...; moreover, it was environmentally sustainable.','medium'),
  (cid,1,7,'gap_fill','The research fills a significant gap in the literature. _____, it offers a novel methodological approach.','Furthermore',NULL,'"Furthermore" adds a second, equally important point in academic writing.','easy'),
  (cid,1,8,'multiple_choice','In academic writing, "moreover" differs from "and" in that it:','signals that the following point is at least as important as (or stronger than) the previous one','["is less formal","signals that the following point is at least as important as (or stronger than) the previous one","introduces a contrast","introduces an example"]','"Moreover" indicates that the additional point adds weight to the argument, not just extra information.','medium'),

  -- BLOCK 2: Contrast Connectors (however, nevertheless, on the other hand, whereas, despite, although)
  (cid,2,9,'gap_fill','The sample size was large. _____, the results may not be representative of the general population.','However',NULL,'"However" introduces a contrast or qualification. Followed by a comma at the start of a sentence.','easy'),
  (cid,2,10,'multiple_choice','The treatment was experimental. _____, the patients agreed to participate in the trial.','Nevertheless','["Moreover","Nevertheless","Therefore","Furthermore"]','"Nevertheless" = despite this fact. Signals that the second point holds even given the problem stated before.','medium'),
  (cid,2,11,'gap_fill','_____ (on the other hand), critics argue that the economic benefits do not outweigh the environmental costs.','On the other hand',NULL,'"On the other hand" introduces an alternative viewpoint or contrasting perspective.','easy'),
  (cid,2,12,'multiple_choice','Northern European countries have high levels of social welfare. _____, many Southern European nations face significant economic inequality.','By contrast','["Furthermore","By contrast","As a result","In addition"]','"By contrast" compares two situations that differ significantly from each other.','medium'),
  (cid,2,13,'gap_fill','_____ (despite) the economic challenges, the country managed to reduce its carbon emissions by 20%.','Despite',NULL,'"Despite + noun phrase" introduces a contrast. → Despite the economic challenges, the country managed to.','easy'),
  (cid,2,14,'multiple_choice','_____ urban populations tend to have higher incomes, they often experience greater levels of social isolation.','Although','["Because","Although","Therefore","Moreover"]','"Although" introduces a concessive clause: the first clause is true, but the second clause provides a contrasting reality.','medium'),
  (cid,2,15,'gap_fill','_____ (whereas) the first group showed significant improvement, the control group showed no change.','Whereas',NULL,'"Whereas" is used to contrast two directly opposing situations in the same sentence.','medium'),
  (cid,2,16,'multiple_choice','Which sentence uses a contrast connector correctly?','The findings were inconclusive; nevertheless, the study contributed valuable data to the field.','["The findings were inconclusive; nevertheless the study contributed.","The findings were inconclusive; nevertheless, the study contributed valuable data to the field.","The findings were inconclusive nevertheless; the study contributed.","Nevertheless the findings were inconclusive the study contributed."]','"Nevertheless" follows a semicolon and is followed by a comma.','medium'),

  -- BLOCK 3: Cause/Effect Connectors (therefore, consequently, as a result, thus, hence)
  (cid,3,17,'gap_fill','The funding was cut significantly. _____, several research projects had to be abandoned.','Therefore/Consequently/As a result',NULL,'Any cause-effect connector works here. The second sentence states the consequence of the funding cut.','easy'),
  (cid,3,18,'multiple_choice','The temperature exceeded 40°C for three consecutive weeks. _____, crop yields were severely reduced.','Consequently','["However","Moreover","Consequently","Although"]','"Consequently" states that the extreme heat was the direct cause of the reduction in crop yields.','easy'),
  (cid,3,19,'gap_fill','Water supplies in the region have been depleted. _____ (as a result), local communities face severe shortages.','As a result',NULL,'"As a result" introduces the consequence of the situation described in the previous sentence.','easy'),
  (cid,3,20,'multiple_choice','The population increased rapidly without corresponding infrastructure development. _____, urban areas became severely overcrowded.','Thus','["Nevertheless","Furthermore","Thus","Whereas"]','"Thus" (formal) signals that the overcrowding was a consequence of the population increase.','medium'),
  (cid,3,21,'gap_fill','The data were insufficient to draw meaningful conclusions. _____ (therefore), a follow-up study was commissioned.','Therefore',NULL,'"Therefore" introduces a logical consequence or decision based on the previous information.','easy'),
  (cid,3,22,'multiple_choice','In academic writing, "hence" is most similar in meaning to:','therefore','["however","moreover","although","therefore"]','"Hence" means "for this reason / therefore." It is a formal, somewhat archaic connector used mainly in academic texts.','medium'),
  (cid,3,23,'gap_fill','The experiment produced unexpected results. _____ (consequently), the theoretical model had to be revised.','Consequently',NULL,'"Consequently" states the logical result of the unexpected experimental outcomes.','easy'),
  (cid,3,24,'multiple_choice','Which sentence correctly uses "as a result"?','Air temperatures have risen; as a result, polar ice is melting at an accelerated rate.','["Air temperatures have risen as a result, polar ice is melting.","Air temperatures have risen; as a result, polar ice is melting at an accelerated rate.","As a result air temperatures have risen polar ice is melting.","Air temperatures, as a result, have risen and polar ice is melting."]','"As a result" typically follows a semicolon (or period) and is followed by a comma.','medium'),

  -- BLOCK 4: Exemplification Connectors (for instance, for example, such as, namely)
  (cid,4,25,'gap_fill','Many factors contribute to academic success, _____ (for example), study habits and motivation.','for example',NULL,'"For example" introduces a specific illustration of the general point made in the main clause.','easy'),
  (cid,4,26,'multiple_choice','Several countries have implemented carbon taxes, _____ Sweden and Canada.','such as','["for example","namely","for instance","such as"]','"Such as" introduces examples within a list. It does not require a comma before the examples (unlike "for example").','easy'),
  (cid,4,27,'gap_fill','Two primary factors were identified, _____ (namely) increased CO₂ levels and rising sea temperatures.','namely',NULL,'"Namely" introduces a specific, exhaustive list of what was just referred to. → Two primary factors, namely X and Y.','medium'),
  (cid,4,28,'multiple_choice','Renewable energy sources, _____ solar and wind power, have become increasingly cost-competitive.','such as','["for example","namely","for instance","such as"]','"Such as" is used within a sentence to give examples from a larger set. No comma needed before the examples.','easy'),
  (cid,4,29,'gap_fill','Several advanced economies have achieved carbon neutrality. _____ (for instance), Norway reached this milestone in 2020.','For instance',NULL,'"For instance" introduces a specific example to illustrate the general statement. Interchangeable with "for example."','easy'),
  (cid,4,30,'multiple_choice','Which sentence uses "namely" correctly?','The committee made three recommendations, namely the adoption of renewable energy targets, increased public funding, and stricter emissions standards.','["The committee made recommendations for example the adoption of renewable energy.","The committee made three recommendations, namely the adoption of renewable energy targets, increased public funding, and stricter emissions standards.","The committee made three recommendations, such as them being the adoption of targets.","Namely, the committee made recommendations about energy."]','"Namely" introduces a complete, specific list of the items referred to by the previous noun.','medium'),
  (cid,4,31,'gap_fill','The diet of several marine mammals, _____ (such as) dolphins and seals, has been affected by overfishing.','such as',NULL,'"Such as" introduces examples within a sentence without requiring punctuation changes.','easy'),
  (cid,4,32,'multiple_choice','The key difference between "for example" and "namely" is that "namely":','specifies all items in a set, whereas "for example" gives only some examples','["is less formal","specifies all items in a set, whereas \"for example\" gives only some examples","can only be used at the beginning of a sentence","is followed by a semicolon, not a comma"]','"Namely" presents a complete, exhaustive specification. "For example" presents a selection from a larger set.','hard'),

  -- BLOCK 5: TOEFL Academic – Concession Connectors
  (cid,5,33,'gap_fill','[TOEFL Reading] _____ (although) the evidence is compelling, further replication is required before drawing definitive conclusions.','Although',NULL,'"Although" introduces a concession — the first clause acknowledges a point while the main clause limits or contrasts it.','easy'),
  (cid,5,34,'multiple_choice','[TOEFL Reading] _____ the economic costs were high, the long-term environmental benefits justified the investment.','Even though','["Because","Even though","Therefore","Moreover"]','"Even though" (stronger than "although") concedes the high cost but prioritizes the benefit.','medium'),
  (cid,5,35,'gap_fill','[TOEFL Reading] _____ (while) some critics argue that the policy is premature, the majority of evidence supports immediate action.','While',NULL,'"While" used at the start of a clause introduces a concession or contrast with the main clause.','medium'),
  (cid,5,36,'multiple_choice','[TOEFL Reading] "The study had a small sample size. _____, its findings align closely with those of larger investigations."','Nevertheless','["Moreover","As a result","Nevertheless","In addition"]','"Nevertheless" = despite this limitation, the following point still holds. Perfect for conceding a weakness.','medium'),
  (cid,5,37,'gap_fill','[TOEFL Listening] The professor acknowledged that _____ (despite) initial setbacks, the research team persisted.','despite',NULL,'"Despite + noun phrase" introduces a concession. → Despite initial setbacks, the team persisted.','easy'),
  (cid,5,38,'multiple_choice','[TOEFL Reading] "_____ the limitations of this approach are acknowledged, the results are considered significant."','While','["Therefore","Moreover","While","As a result"]','"While the limitations are acknowledged" = concessive clause acknowledging a weakness before the main point.','medium'),
  (cid,5,39,'gap_fill','[TOEFL Reading] _____ (even though) the drug showed promise in animal trials, human trials produced inconclusive results.','Even though',NULL,'"Even though" concedes the positive animal trial results while contrasting them with the human trial outcomes.','medium'),
  (cid,5,40,'multiple_choice','[TOEFL Listening] The professor used "however" to:','signal a contrast or limitation to the point previously made','["add more supporting evidence","introduce an example","signal a contrast or limitation to the point previously made","introduce a cause-effect relationship"]','"However" introduces a contrast, exception, or qualifying point — not additional support.','easy'),

  -- BLOCK 6: TOEFL Academic – Summation Connectors
  (cid,6,41,'gap_fill','[TOEFL Reading] _____ (in conclusion), the evidence strongly supports the hypothesis that urbanization drives biodiversity loss.','In conclusion',NULL,'"In conclusion" is used to introduce the final summary or main takeaway of an argument.','easy'),
  (cid,6,42,'multiple_choice','[TOEFL Reading] Which connector is most appropriate to begin a concluding paragraph?','To summarize','["Furthermore","However","Nevertheless","To summarize"]','"To summarize" and "In conclusion" introduce summations. The others are used mid-argument.','easy'),
  (cid,6,43,'gap_fill','[TOEFL Reading] _____ (overall), the findings suggest that the intervention was moderately effective across all age groups.','Overall',NULL,'"Overall" introduces a general conclusion or summary of multiple findings.','easy'),
  (cid,6,44,'multiple_choice','[TOEFL Listening] The professor concludes: "_____, the three main causes of deforestation — agriculture, logging, and urbanization — all require policy intervention." Which connector fits best?','In summary','["For example","In summary","However","As a result"]','"In summary" introduces a recapitulation of the main points before the conclusion.','easy'),
  (cid,6,45,'gap_fill','[TOEFL Reading] _____ (to summarize), while the study has several methodological limitations, it represents a significant contribution to the field.','To summarize',NULL,'"To summarize" is used to concisely restate the key argument before ending an academic paper or section.','easy'),
  (cid,6,46,'multiple_choice','[TOEFL Reading] "In conclusion" differs from "therefore" in that "in conclusion":','introduces a final summary, while "therefore" shows a logical consequence','["is less formal","introduces a final summary, while \"therefore\" shows a logical consequence","can only be used in spoken language","is followed by a semicolon"]','"In conclusion" signals the end of an argument (meta-discourse). "Therefore" shows logical causation.','medium'),
  (cid,6,47,'gap_fill','[TOEFL Reading] _____ (in sum), the data challenge the prevailing assumption that economic growth and environmental protection are incompatible.','In sum',NULL,'"In sum" is a concise academic connector that introduces the main takeaway of an argument.','medium'),
  (cid,6,48,'multiple_choice','[TOEFL Listening] The professor uses "all in all" to:','provide a general evaluation of the evidence presented','["introduce an example","signal a contrast","provide a general evaluation of the evidence presented","add more information"]','"All in all" is a discourse marker that introduces a balanced, overall assessment.','medium'),

  -- BLOCK 7: TOEFL Academic – Identifying Connector Function
  (cid,7,49,'multiple_choice','[TOEFL Reading] "The research is groundbreaking; however, it requires further validation." What is the function of "however"?','to introduce a limitation or qualifying point','["to add information","to introduce a limitation or qualifying point","to give an example","to state a result"]','"However" signals a contrast or limitation to the positive claim made in the first clause.','easy'),
  (cid,7,50,'gap_fill','[TOEFL Reading] Identify the connector type: "The method was reliable; consequently, it was adopted by most laboratories in the field." → Consequently signals a _____ relationship.','cause-effect',NULL,'"Consequently" introduces the result or consequence of the previous statement. → cause-effect relationship.','easy'),
  (cid,7,51,'multiple_choice','[TOEFL Reading] "Species such as polar bears and Arctic foxes are especially vulnerable to climate change." What is the function of "such as"?','to introduce examples from a larger category','["to summarize a list","to contrast two items","to introduce examples from a larger category","to signal a conclusion"]','"Such as" introduces examples (polar bears, Arctic foxes) from a broader category (vulnerable species).','easy'),
  (cid,7,52,'gap_fill','[TOEFL Listening] "The results were surprising; _____ (furthermore), they contradicted two decades of prior research." → Furthermore here signals _____ information.','additional',NULL,'"Furthermore" adds another point that strengthens or extends the previous statement.','easy'),
  (cid,7,53,'multiple_choice','[TOEFL Reading] "Despite its limitations, the study remains the most comprehensive analysis of urban biodiversity to date." What does "despite" signal?','a concession — acknowledging a weakness before affirming the value of the study','["a contrast between two studies","a concession — acknowledging a weakness before affirming the value of the study","a cause-effect relationship","an example"]','"Despite its limitations" concedes a weakness; the main clause then reasserts the study''s value.','medium'),
  (cid,7,54,'gap_fill','[TOEFL Reading] _____ (whereas) traditional methods require weeks of processing, the new algorithm produces results in minutes.','Whereas',NULL,'"Whereas" compares two contrasting methods in the same sentence — appropriate for direct comparisons.','medium'),
  (cid,7,55,'multiple_choice','[TOEFL Listening] The professor used "in other words" to:','restate a complex idea in simpler terms for clarity','["introduce an opposing viewpoint","restate a complex idea in simpler terms for clarity","signal a conclusion","add a supporting example"]','"In other words" is a reformulation marker used to clarify or simplify a previous statement.','easy'),
  (cid,7,56,'gap_fill','[TOEFL Reading] The intervention produced positive results. _____ (as a result), funding was extended for a further three years.','As a result',NULL,'"As a result" introduces the consequence (funding extension) of the positive results. Cause-effect connector.','easy'),

  -- BLOCK 8: TOEFL Academic – Connector Selection in Full Paragraphs
  (cid,8,57,'multiple_choice','[TOEFL Reading] Choose the connector that best completes this paragraph: "Air pollution has serious health consequences. _____, it disproportionately affects low-income communities that cannot afford to relocate."','Furthermore','["However","Nevertheless","Furthermore","In conclusion"]','"Furthermore" adds an additional, stronger point about the unequal distribution of harm.','medium'),
  (cid,8,58,'gap_fill','[TOEFL Reading] "Technology has transformed education. _____, access to digital tools remains unequal across socioeconomic groups." → _____ signals contrast.','However',NULL,'"However" introduces a limitation or contrasting reality to the positive claim about technology.','easy'),
  (cid,8,59,'multiple_choice','[TOEFL Reading] "The study involved participants from multiple countries, _____ the United States, Germany, and Japan." Which connector is needed?','namely','["for example","such as","namely","in other words"]','"Namely" is used because a complete, exhaustive list of all three countries follows. "Such as" implies partial examples.','hard'),
  (cid,8,60,'gap_fill','[TOEFL Listening] "The professor noted that several species face extinction. _____ (for instance), the Sumatran tiger population has fallen below 400."','For instance',NULL,'"For instance" introduces a specific example to illustrate the general claim about species extinction.','easy'),
  (cid,8,61,'multiple_choice','[TOEFL Reading] "Economic inequality has increased globally. _____, social mobility has declined in many developed nations."','Furthermore,'['["As a result,","Furthermore,","However,","Namely,"]','"Furthermore" adds an additional, related negative trend. "As a result" would imply the inequality caused the mobility decline.','hard'),
  (cid,8,62,'gap_fill','[TOEFL Reading] "Emissions from transportation account for a significant proportion of greenhouse gases. _____ (therefore), reducing car use should be a policy priority."','Therefore',NULL,'"Therefore" introduces the logical conclusion derived from the information about transportation emissions.','easy'),
  (cid,8,63,'multiple_choice','[TOEFL Reading] "The two approaches differ significantly: _____ the first method is time-intensive, the second produces faster but less reliable results."','whereas','["therefore","furthermore","whereas","in conclusion"]','"Whereas" directly contrasts two items with opposite or differing characteristics in the same sentence.','medium'),
  (cid,8,64,'gap_fill','[TOEFL Reading] _____ (in conclusion), the evidence suggests that investing in early childhood education yields significant long-term economic and social returns.','In conclusion',NULL,'"In conclusion" introduces the final, overall takeaway at the end of an academic argument.','easy'),

  -- BLOCK 9: TOEFL Speaking Tasks
  (cid,9,65,'production','[TOEFL Speaking — 45s] The reading passage argues that remote work increases productivity. The lecture, however, presents evidence that remote work can lead to social isolation and reduced team cohesion. Summarize the main points of the lecture and explain how they challenge the reading. Use academic connectors such as "however," "furthermore," "as a result," and "nevertheless." You have 45 seconds.','',NULL,'Practice connectors: "The reading argues that... However, the professor suggests that... Furthermore,... As a result,... Nevertheless,..."','hard'),
  (cid,9,66,'production','[TOEFL Speaking — 45s] Some people believe that universities should focus primarily on academic subjects. Others argue that practical skills and career preparation are equally important. Discuss both views and give your opinion. Use connectors of contrast and addition in your response. You have 45 seconds.','',NULL,'Use: "On the other hand,..." "Moreover,..." "However,..." "Furthermore,..." "In conclusion,..."','medium'),
  (cid,9,67,'production','[TOEFL Speaking — 45s] Describe a significant change in your city or country over the last decade. Explain the causes of this change and its effects on the population. Use cause-effect connectors ("as a result," "consequently," "therefore") and addition connectors. You have 45 seconds.','',NULL,'Structure: "Over the last decade, X has changed significantly. As a result,... Furthermore,... Consequently,..."','medium'),

  -- BLOCK 10: TOEFL Writing Tasks
  (cid,10,68,'production','[TOEFL Writing] Write an essay (150+ words) discussing the advantages and disadvantages of globalization. Use a variety of academic connectors from each category: addition (furthermore, moreover), contrast (however, nevertheless, whereas), cause-effect (therefore, consequently), exemplification (for example, such as), and summation (in conclusion). Aim to use at least one connector from each category.','',NULL,'Target connectors: "Furthermore,..." "However,..." "As a result,..." "For example,..." "In conclusion,..." "Nevertheless,..." "Whereas..."','hard'),
  (cid,10,69,'production','[TOEFL Writing] Integrated task: The reading argues that nuclear energy should be expanded as a low-carbon alternative to fossil fuels. The lecture challenges this claim by pointing to safety concerns and waste disposal issues. Write a 150+ word response summarizing the relationship between the reading and the lecture. Use at least five different academic connectors to organize your response clearly.','',NULL,'Connectors to include: "However," "Furthermore," "As a result," "In contrast," "Nevertheless," "Moreover," "Therefore."','hard'),
  (cid,10,70,'production','[TOEFL Writing] Choose ONE of the following topics and write a well-organized essay (150+ words) that uses at least SIX different academic connectors. Underline each connector you use. Topic A: "The advantages and disadvantages of studying abroad." Topic B: "Should governments provide universal basic income?" Topic C: "The role of sport in promoting national identity."','',NULL,'Connector targets: addition, contrast, cause-effect, exemplification, concession, summation. Underline each for self-assessment.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
